{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policy does not allow 'AssumeRole' permission across all services",
      "resource": "aws_iam_user_policy_attachment.privesc18-PassExistingRoleToNewGlueDevEndpoint-user-attach-policy",
      "severity": "HIGH",
      "explanation": "The attached policy may allow assuming any role, potentially leading to privilege escalation."
    }
  ],
  "patched_code": "resource "aws_iam_user_policy_attachment" "privesc18-PassExistingRoleToNewGlueDevEndpoint-user-attach-policy" {
  user       = aws_iam_user.privesc18-PassExistingRoleToNewGlueDevEndpoint-user.name
  policy_arn = aws_iam_policy.privesc18-PassExistingRoleToNewGlueDevEndpoint.arn
}

data "aws_iam_policy_document" "privesc18-PassExistingRoleToNewGlueDevEndpoint" {
  statement {
    effect = "Allow"
    actions = [
      "iam:PassRole",
    ]
    resources = [
      "arn:aws:iam::*:role/*",
    ]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values = [
        "glue.amazonaws.com",
      ]
    }
  }
}

resource "aws_iam_policy" "privesc18-PassExistingRoleToNewGlueDevEndpoint" {
  name        = "privesc18-PassExistingRoleToNewGlueDevEndpoint"
  description = "Policy for privesc18-PassExistingRoleToNewGlueDevEndpoint"
  policy      = data.aws_iam_policy_document.privesc18-PassExistingRoleToNewGlueDevEndpoint.json
}",
  "fix_summary": "Added a new IAM policy document with restricted 'iam:PassRole' permissions to only allow passing roles to 'glue.amazonaws.com' service, and updated the existing IAM policy to use this new document."
}
